export const normalizePeriodType = (
  periodType?: string,
  fallbackPeriodType?: string,
) => {
  if (!periodType) return fallbackPeriodType;

  const normalizedPeriodType = periodType.toUpperCase();

  return normalizedPeriodType === 'LQ' ? 'QTD' : normalizedPeriodType;
};
